import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const History = () => {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchHistory();
    const interval = setInterval(fetchHistory, 10000);
    return () => clearInterval(interval);
  }, []);

  const fetchHistory = async () => {
    try {
      const result = await axios.get(`${API_URL}/history`);
      setHistory(result.data.history || []);
      setError(null);
    } catch (err) {
      setError('Failed to load history: ' + err.message);
      setHistory([]);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="component-container"><p>Loading history...</p></div>;
  }

  return (
    <div className="component-container">
      <h2>Processing History</h2>
      
      <div style={{ textAlign: 'center', marginBottom: '20px' }}>
        <button onClick={fetchHistory} className="button">
          Refresh
        </button>
      </div>

      {error && <div className="error">{error}</div>}

      {history.length === 0 ? (
        <p style={{ textAlign: 'center', color: '#666' }}>No processing history yet.</p>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ddd', backgroundColor: '#f5f5f5' }}>
                <th style={{ padding: '12px', textAlign: 'left' }}>Type</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Output File</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Details</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Timestamp</th>
              </tr>
            </thead>
            <tbody>
              {history.map((item, index) => (
                <tr key={index} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '12px' }}>
                    <span style={{ textTransform: 'capitalize', fontWeight: '500' }}>
                      {item.type}
                    </span>
                  </td>
                  <td style={{ padding: '12px' }}>
                    {item.type === 'video' && item.output ? (
                      <a 
                        href={`${API_URL}/download/${item.output}`} 
                        download
                        style={{ color: '#0066cc', textDecoration: 'none' }}
                      >
                        {item.output}
                      </a>
                    ) : (
                      item.output || '-'
                    )}
                  </td>
                  <td style={{ padding: '12px' }}>
                    {item.frames ? `${item.frames} frames` : '-'}
                  </td>
                  <td style={{ padding: '12px', fontSize: '14px', color: '#666' }}>
                    {new Date(item.timestamp).toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default History;
